#include <stdbool.h>

bool solution(int T, int N, int M, const int customer[], int customer_len) {
    for (int i = 0; i < M; i++) {
        int made = customer[i] / T * N;  // customer[i]초까지 만든 호떡 수
        int sold = i;                    // 앞 손님 i명이 이미 사 간 호떡 수
        if (made - sold <= 0)            // 남은 호떡이 없으면 장사 실패
            return false;
    }
    return true;
}

problems.inputCheck:
def valid(T, N, M, customer):
    ints = lambda v: isinstance(v, int) and not isinstance(v, bool)
    if not (ints(T) and ints(N) and ints(M) and isinstance(customer, list)):
        return False
    if not (1 <= T <= 200 and 1 <= N <= 5 and 1 <= M <= 100 and len(customer) == M):
        return False
    if not all(ints(c) and 1 <= c <= 1000 for c in customer):
        return False
    return all(customer[i] < customer[i + 1] for i in range(M - 1))

